import React, { useState, useEffect } from 'react';
import { Link, useNavigate, useLocation } from 'react-router-dom';
import { useDispatch, useSelector } from 'react-redux';
import { useForm } from 'react-hook-form';
import { EyeIcon, EyeSlashIcon, ShieldCheckIcon } from '@heroicons/react/24/outline';
import { login, clearError } from '../../store/slices/authSlice';
import Button from '../../components/ui/Button';
import Card from '../../components/ui/Card';
import toast from 'react-hot-toast';

const Login = () => {
  const [showPassword, setShowPassword] = useState(false);
  const { loading, error } = useSelector((state) => state.auth);
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const location = useLocation();

  const from = location.state?.from?.pathname || '/dashboard';

  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm();

  useEffect(() => {
    dispatch(clearError());
  }, [dispatch]);

  useEffect(() => {
    if (error) {
      toast.error(error);
    }
  }, [error]);

  const onSubmit = async (data) => {
    try {
      await dispatch(login(data)).unwrap();
      toast.success('Welcome back!');
      navigate(from, { replace: true });
    } catch (error) {
      // Error is handled by the error state and toast above
    }
  };

  const demoAccounts = [
    { email: 'demo.worker@taskapp.com', password: 'SecurePass123!', role: 'Worker', description: 'Experienced freelancer' },
    { email: 'demo.employer@taskapp.com', password: 'SecurePass123!', role: 'Employer', description: 'Business account' },
    { email: 'demo.admin@taskapp.com', password: 'admin123', role: 'Admin', description: 'Platform administrator' },
  ];

  const handleDemoLogin = async (email, password) => {
    try {
      await dispatch(login({ email, password })).unwrap();
      toast.success('Welcome back!');
      navigate(from, { replace: true });
    } catch (error) {
      // Error is handled by the error state and toast above
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gradient-to-br from-primary-50 via-white to-secondary-50 py-8 sm:py-12 px-4 sm:px-6 lg:px-8">
      <div className="max-w-md w-full space-y-8">
        {/* Header */}
        <div className="text-center">
          <div className="flex justify-center mb-6">
            <div className="flex items-center space-x-3 group">
              <img 
                src="/logo task.jpg" 
                alt="TaskApp Logo" 
                className="w-12 h-12 sm:w-14 sm:h-14 rounded-xl object-cover group-hover:scale-105 transition-transform duration-200"
              />
              <span className="text-2xl sm:text-3xl font-bold bg-gradient-to-r from-primary-600 to-secondary-600 bg-clip-text text-transparent">
                TaskApp
              </span>
            </div>
          </div>
          <h2 className="text-2xl sm:text-3xl lg:text-4xl font-bold text-secondary-900 mb-3">
            Welcome Back
          </h2>
          <p className="text-base sm:text-lg text-secondary-600 mb-2">
            Sign in to your professional account
          </p>
          <p className="text-sm sm:text-base text-secondary-500">
            Don't have an account?{' '}
            <Link
              to="/register"
              className="font-semibold text-primary-600 hover:text-primary-500 transition-colors duration-200"
            >
              Create one now
            </Link>
          </p>
        </div>

        {/* Demo Accounts */}
        <Card className="bg-gradient-to-r from-primary-50 to-info-50 border-primary-200">
          <div className="flex items-center mb-3">
            <ShieldCheckIcon className="w-5 h-5 text-primary-600 mr-2" />
            <h3 className="text-sm font-semibold text-primary-900">Demo Accounts</h3>
          </div>
          <div className="space-y-2">
            {demoAccounts.map((account, index) => (
              <button
                key={index}
                onClick={() => handleDemoLogin(account.email, account.password)}
                className="w-full text-left px-3 py-2 text-sm bg-white border border-primary-200 rounded-lg hover:bg-primary-50 hover:border-primary-300 transition-all duration-200 group"
                disabled={loading}
              >
                <div className="flex items-center justify-between">
                  <div>
                    <div className="font-medium text-primary-900 group-hover:text-primary-700">
                      {account.role}
                    </div>
                    <div className="text-primary-600 text-xs">{account.description}</div>
                  </div>
                  <div className="text-xs text-primary-500 opacity-0 group-hover:opacity-100 transition-opacity">
                    Click to login
                  </div>
                </div>
              </button>
            ))}
          </div>
        </Card>

        {/* Login Form */}
        <Card>
          <form className="space-y-6" onSubmit={handleSubmit(onSubmit)}>
            <div className="space-y-4">
              <div>
                <label htmlFor="email" className="block text-sm font-medium text-secondary-700 mb-1">
                  Email address
                </label>
                <input
                  {...register('email', {
                    required: 'Email is required',
                    pattern: {
                      value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
                      message: 'Invalid email address',
                    },
                  })}
                  type="email"
                  className="w-full px-3 py-2 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-colors"
                  placeholder="Enter your email"
                />
                {errors.email && (
                  <p className="mt-1 text-sm text-error-600">{errors.email.message}</p>
                )}
              </div>

              <div>
                <label htmlFor="password" className="block text-sm font-medium text-secondary-700 mb-1">
                  Password
                </label>
                <div className="relative">
                  <input
                    {...register('password', {
                      required: 'Password is required',
                    })}
                    type={showPassword ? 'text' : 'password'}
                    className="w-full px-3 py-2 pr-10 border border-secondary-300 rounded-lg focus:ring-2 focus:ring-primary-500 focus:border-primary-500 transition-colors"
                    placeholder="Enter your password"
                  />
                  <button
                    type="button"
                    className="absolute inset-y-0 right-0 pr-3 flex items-center"
                    onClick={() => setShowPassword(!showPassword)}
                  >
                    {showPassword ? (
                      <EyeSlashIcon className="h-5 w-5 text-secondary-400 hover:text-secondary-600" />
                    ) : (
                      <EyeIcon className="h-5 w-5 text-secondary-400 hover:text-secondary-600" />
                    )}
                  </button>
                </div>
                {errors.password && (
                  <p className="mt-1 text-sm text-error-600">{errors.password.message}</p>
                )}
              </div>
            </div>

            <div className="flex items-center justify-between">
              <div className="text-sm">
                <Link
                  to="/forgot-password"
                  className="font-medium text-primary-600 hover:text-primary-500 transition-colors"
                >
                  Forgot your password?
                </Link>
              </div>
            </div>

            <Button
              type="submit"
              loading={loading}
              className="w-full"
              size="lg"
            >
              Sign in securely
            </Button>
          </form>
        </Card>

        {/* Security Notice */}
        <div className="text-center">
          <p className="text-xs text-secondary-500">
            Protected by enterprise-grade security • SSL encrypted • GDPR compliant
          </p>
        </div>
      </div>
    </div>
  );
};

export default Login;
